import React, { useCallback, useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Paper,
  Typography,
} from '@mui/material';
import { ContentCopy as CopyIcon, Download as DownloadIcon, ExpandMore as ExpandMoreIcon } from '@mui/icons-material';

interface ComplianceJsonPanelProps {
  title: string;
  data: unknown;
  filename?: string;
  defaultCollapsed?: boolean;
}

const ComplianceJsonPanel: React.FC<ComplianceJsonPanelProps> = ({
  title,
  data,
  filename = 'compliance-pack.json',
  defaultCollapsed = true,
}) => {
  const [expanded, setExpanded] = useState(!defaultCollapsed);
  const jsonText = JSON.stringify(data, null, 2);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(jsonText);
    } catch {
      // ignore
    }
  }, [jsonText]);

  const handleDownload = useCallback(() => {
    const blob = new Blob([jsonText], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
  }, [jsonText, filename]);

  if (!data) {
    return <Alert severity="info">No data available for this section yet.</Alert>;
  }

  if (defaultCollapsed && !expanded) {
    return (
      <Accordion
        disableGutters
        elevation={0}
        expanded={expanded}
        onChange={(_, next) => setExpanded(next)}
        sx={{ border: 1, borderColor: 'divider', borderRadius: 1, '&:before': { display: 'none' } }}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Typography variant="body2" color="text.secondary">
            Advanced: view or download JSON export ({title})
          </Typography>
        </AccordionSummary>
        <AccordionDetails>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
            <Typography variant="subtitle2">{title}</Typography>
            <Box sx={{ display: 'flex', gap: 1 }}>
              <Button size="small" startIcon={<CopyIcon />} onClick={handleCopy}>
                Copy JSON
              </Button>
              <Button size="small" variant="outlined" startIcon={<DownloadIcon />} onClick={handleDownload}>
                Download
              </Button>
            </Box>
          </Box>
          <Paper
            variant="outlined"
            component="pre"
            sx={{
              p: 2,
              overflow: 'auto',
              maxHeight: 480,
              fontSize: '0.75rem',
              bgcolor: 'action.hover',
            }}
          >
            {jsonText}
          </Paper>
        </AccordionDetails>
      </Accordion>
    );
  }

  return (
    <Box>
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
        <Typography variant="h6">{title}</Typography>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button size="small" startIcon={<CopyIcon />} onClick={handleCopy}>
            Copy JSON
          </Button>
          <Button size="small" variant="outlined" startIcon={<DownloadIcon />} onClick={handleDownload}>
            Download
          </Button>
        </Box>
      </Box>
      <Paper
        variant="outlined"
        component="pre"
        sx={{
          p: 2,
          overflow: 'auto',
          maxHeight: 480,
          fontSize: '0.75rem',
          bgcolor: 'action.hover',
        }}
      >
        {jsonText}
      </Paper>
    </Box>
  );
};

export default ComplianceJsonPanel;
