import React, { lazy, Suspense, useMemo, useState } from 'react';
import {
  Box,
  CircularProgress,
  Tab,
  Tabs,
  Typography,
} from '@mui/material';
import type { AssuranceClauseWorkflowBundle } from './AssuranceClauseWorkflowPanel';

const IsoGapClosurePanel = lazy(() => import('./IsoGapClosurePanel'));
const BrsrGapClosurePanel = lazy(() => import('./BrsrGapClosurePanel'));
const CbamGapClosurePanel = lazy(() => import('./CbamGapClosurePanel'));
const ThirdPartyVerifierPanel = lazy(() => import('./ThirdPartyVerifierPanel'));
const AssuranceClauseWorkflowPanel = lazy(() => import('./AssuranceClauseWorkflowPanel'));

export type GapWorkspaceTab = 'iso' | 'brsr' | 'cbam' | 'assurance';

type ComplianceGapWorkspaceProps = {
  period?: string;
  defaultTab?: GapWorkspaceTab;
  showCbam?: boolean;
  assuranceClauseWorkflows?: AssuranceClauseWorkflowBundle | null;
  hideTechnicalDetails?: boolean;
  showExpertDetails?: boolean;
};

const TabLoader: React.FC = () => (
  <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
    <CircularProgress size={28} />
  </Box>
);

const ComplianceGapWorkspace: React.FC<ComplianceGapWorkspaceProps> = ({
  period = 'annual',
  defaultTab = 'iso',
  showCbam = false,
  assuranceClauseWorkflows = null,
  hideTechnicalDetails = true,
  showExpertDetails = false,
}) => {
  const hideClauseDetail = hideTechnicalDetails && !showExpertDetails;
  const [tab, setTab] = useState<GapWorkspaceTab>(defaultTab);
  const [visited, setVisited] = useState<Set<GapWorkspaceTab>>(() => new Set([defaultTab]));

  const tabs = useMemo(() => {
    const items: Array<{ id: GapWorkspaceTab; label: string }> = [
      { id: 'iso', label: 'ISO 14064' },
      { id: 'brsr', label: 'BRSR' },
      { id: 'assurance', label: 'Assurance' },
    ];
    if (showCbam) {
      items.splice(2, 0, { id: 'cbam', label: 'CBAM' });
    }
    return items;
  }, [showCbam]);

  const handleTabChange = (_: React.SyntheticEvent, value: GapWorkspaceTab) => {
    setTab(value);
    setVisited((prev) => new Set(prev).add(value));
  };

  const renderTab = () => {
    if (!visited.has(tab)) {
      return <TabLoader />;
    }
    return (
      <Suspense fallback={<TabLoader />}>
        {tab === 'iso' ? <IsoGapClosurePanel period={period} /> : null}
        {tab === 'brsr' ? <BrsrGapClosurePanel period={period} /> : null}
        {tab === 'cbam' && showCbam ? <CbamGapClosurePanel period={period} /> : null}
        {tab === 'assurance' ? (
          <ThirdPartyVerifierPanel period={period} embedded />
        ) : null}
      </Suspense>
    );
  };

  return (
    <Box>
      <Typography variant="subtitle1" fontWeight={600} gutterBottom>
        Gap details by standard
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 640 }}>
        Open only the standard you are working on — details load when you select a tab.
      </Typography>
      <Tabs
        value={tab}
        onChange={handleTabChange}
        variant="scrollable"
        scrollButtons="auto"
        sx={{ mb: 2, borderBottom: 1, borderColor: 'divider' }}
      >
        {tabs.map((entry) => (
          <Tab key={entry.id} value={entry.id} label={entry.label} />
        ))}
      </Tabs>
      {renderTab()}
      {!hideClauseDetail && assuranceClauseWorkflows ? (
        <Box sx={{ mt: 3 }}>
          <Suspense fallback={<TabLoader />}>
            <AssuranceClauseWorkflowPanel
              bundle={assuranceClauseWorkflows}
              frameworkFilter="all"
              title="Clause-level detail (for auditors)"
            />
          </Suspense>
        </Box>
      ) : null}
    </Box>
  );
};

export default ComplianceGapWorkspace;
